/* From Uiverse.io by WittyHydra - Tags: notification */
.__UIV_SCOPE__ .notification {
  --bg-color: #fff;
  --text-color: #1c1f2b;
  --highlight-color: #fc9a32;
  --button-color: #3d3f4e;
  --button-color-hover: #27282f;
  position: relative;
  width: 300px;
  height: 100px;
  background-color: var(--bg-color);
  border-radius: 10px;
  -webkit-box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  overflow: hidden;
}

@media (prefers-color-scheme: dark) {
  .__UIV_SCOPE__ .notification {
    --bg-color: #1c1f2b;
    --text-color: #fff;
    --highlight-color: #fc9a32;
    --button-color: #3d3f4e;
    --button-color-hover: #27282f;
  }
}

.__UIV_SCOPE__ .notification-top {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background-color: var(--highlight-color);
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  -webkit-box-pack: center;
  -ms-flex-pack: center;
  justify-content: center;
  -webkit-transform: translateY(-100%);
  -ms-transform: translateY(-100%);
  transform: translateY(-100%);
  -webkit-animation: slide-down 1s ease-out forwards;
  animation: slide-down 1s ease-out forwards;
}

.__UIV_SCOPE__ .notification-bottom {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 50%;
  background-color: var(--bg-color);
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  -webkit-box-pack: justify;
  -ms-flex-pack: justify;
  justify-content: space-between;
  padding: 20px;
}

.__UIV_SCOPE__ .level-up {
  color: var(--text-color);
  font-size: 24px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  -webkit-animation: rotate-text 1s ease-in-out;
  animation: rotate-text 1s ease-in-out;
}

.__UIV_SCOPE__ .level {
  color: var(--text-color);
  font-size: 20px;
  font-weight: bold;
  margin-right: 10px;
}

.__UIV_SCOPE__ .next-level-button {
  background-color: var(--button-color);
  color: var(--text-color);
  border: none;
  border-radius: 5px;
  padding: 8px 16px;
  cursor: pointer;
  -webkit-transition: background-color 0.3s ease-out;
  transition: background-color 0.3s ease-out;
}

.__UIV_SCOPE__ .next-level-button {
  background-color: #efefef;
  color: #000;
  font-weight: 600;
  padding: 5px 10px;
  border: none;
  border-radius: 5px;
  -webkit-transition: all 0.3s ease-in-out;
  transition: all 0.3s ease-in-out;
  -webkit-box-shadow: 0px 0px 10px #888888;
  box-shadow: 0px 0px 10px #888888;
}

@-webkit-keyframes slide-down {
  from {
    -webkit-transform: translateY(-100%);
    transform: translateY(-100%);
  }

  to {
    -webkit-transform: translateY(0);
    transform: translateY(0);
  }
}

@keyframes slide-down {
  from {
    -webkit-transform: translateY(-100%);
    transform: translateY(-100%);
  }

  to {
    -webkit-transform: translateY(0);
    transform: translateY(0);
  }
}

@-webkit-keyframes rotate-text {
  0% {
    -webkit-transform: rotateX(90deg);
    transform: rotateX(90deg);
    opacity: 0;
  }

  100% {
    -webkit-transform: rotateX(0);
    transform: rotateX(0);
    opacity: 1;
  }
}

@keyframes rotate-text {
  0% {
    -webkit-transform: rotateX(90deg);
    transform: rotateX(90deg);
    opacity: 0;
  }

  100% {
    -webkit-transform: rotateX(0);
    transform: rotateX(0);
    opacity: 1;
  }
}

.__UIV_SCOPE__ .next-level-button:hover {
  background-color: aqua;
  color: #000;
  -webkit-transform: scale(1.1);
  -ms-transform: scale(1.1);
  transform: scale(1.1);
  -webkit-box-shadow: 0px 0px 15px #888888;
  box-shadow: 0px 0px 15px #888888;
}

.__UIV_SCOPE__ .notification {
  background-color: #1e2b3c;
  color: #c3daf6;
}

.__UIV_SCOPE__ .notification:hover {
  background-color: #c3daf6;
  color: #1e2b3c;
}

.__UIV_SCOPE__ .next-level-button:hover {
  background-color: #1e2b3c;
  color: #c3daf6;
}

/* Light Mode */
.__UIV_SCOPE__ .notification {
  background-color: #c3daf6;
  color: #1e2b3c;
}

.__UIV_SCOPE__ .notification:hover {
  background-color: #1e2b3c;
  color: #c3daf6;
}

.__UIV_SCOPE__ .next-level-button:hover {
  background-color: #c3daf6;
  color: #1e2b3c;
}
